<script setup lang="ts">
import {ref,watch,onMounted} from 'vue';import type {Raster} from './port.ts';
const props=defineProps<{data:Raster;start:number;end:number;windowMs:number;boundaries?:number[]}>();const canvas=ref<HTMLCanvasElement>();
function paint(){const target=canvas.value;if(!target)return;const r=props.data,bytes=atob(r.pixels),off=document.createElement('canvas');off.width=r.width;off.height=r.height;const ctx=off.getContext('2d')!,img=ctx.createImageData(r.width,r.height);for(let y=0;y<r.height;y++)for(let x=0;x<r.width;x++){const p=((r.height-1-y)*r.width+x)*4,v=bytes.charCodeAt(y*r.width+x);img.data[p]=img.data[p+1]=img.data[p+2]=v;img.data[p+3]=255;}ctx.putImageData(img,0,0);target.width=1000;target.height=220;const out=target.getContext('2d')!;out.fillStyle='white';out.fillRect(0,0,1000,220);out.drawImage(off,(r.t0-props.start)/(props.end-props.start)*1000,0,Math.max(.001,r.t1-r.t0)/(props.end-props.start)*1000,220);}
onMounted(paint);watch(()=>[props.data,props.start,props.end],paint);
</script>
<template><div class="synthesis-spectrum"><div class="track-label">语谱图 · {{windowMs}} ms · {{data.fmax.toFixed(0)}} Hz</div><div class="spectrum-plot" :data-start="start" :data-end="end"><canvas ref="canvas" role="img" aria-label="合成结果语谱图"/><svg viewBox="0 0 1000 100" preserveAspectRatio="none" aria-hidden="true"><path v-for="t in boundaries??[]" :key="t" class="boundary" :d="`M${(t-start)/(end-start)*1000},0V100`"/></svg></div><div class="axis"><span v-for="i in 5" :key="i">{{(start+(i-1)*(end-start)/4).toFixed(3)}}{{i===5?' s':''}}</span></div></div></template>
<style scoped>.synthesis-spectrum{display:flex;flex-direction:column;min-height:0;border:1px solid var(--border);border-radius:8px;overflow:hidden}.spectrum-plot{position:relative;flex:1;min-height:80px;margin-left:72px;margin-right:24px;overflow:hidden}canvas{display:block;width:100%;height:100%;position:absolute;inset:0}.spectrum-plot svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.boundary{stroke:var(--warning);stroke-dasharray:4 4;vector-effect:non-scaling-stroke}.axis{display:flex;justify-content:space-between;margin:0 24px 0 72px;font-family:var(--font-figure);font-size:var(--figure-size)}</style>
